def page_header(title: str, subtitle: str=''):
    """页面标题 — 大号加粗"""
    sub_html = f'<div class="page-subtitle">{subtitle}</div>' if subtitle else ''
    st.markdown(f'<div class="page-title">{title}</div>{sub_html}', unsafe_allow_html=True)

def section_banner(title: str, subtitle: str='', color: str=None):
    """区块标题 — 底线分隔，无背景填充"""
    st.markdown(f'\n    <div class="section-banner">\n        <span class="section-banner-title">{title}</span>\n        <span class="section-banner-sub">{subtitle}</span>\n    </div>\n    ', unsafe_allow_html=True)

def dim_card(title: str, score: int, analysis: str, sub_items=None, extra=None):
    """维度评估卡片"""
    if score >= 60:
        color = COLORS['primary']
        status = '达标'
    elif score >= 40:
        color = COLORS['accent']
        status = '待改善'
    else:
        color = COLORS['danger']
        status = '风险'
    analysis_display = analysis[:400] if len(analysis) > 400 else analysis
    st.markdown(f'\n    <div class="dim-card" style="border-left-color:{color};">\n        <div class="dim-card-header">\n            <span class="dim-card-title">{title}</span>\n            <span class="dim-card-score" style="color:{color};">\n                {score}<span class="dim-card-score-unit"> 分</span>\n            </span>\n        </div>\n        <div style="background:#f0f0f0;height:3px;overflow:hidden;margin-bottom:12px;">\n            <div style="height:100%;width:{score}%;background:{color};transition:width 0.6s;"></div>\n        </div>\n        <div class="dim-card-body">{analysis_display}</div>\n    </div>\n    ', unsafe_allow_html=True)
    if sub_items or extra:
        with st.expander('详细分析', expanded=False):
            if sub_items:
                for si in sub_items:
                    ic = {'pass': '✅', 'warning': '⚠️', 'block': '🚫', '满足': '✅', '存疑': '⚠️', '不满足': '❌', '充足': '✅', '不足': '⚠️', '缺失': '❌'}.get(si.get('status', ''), '⚪')
                    sub_s = si.get('score', None)
                    score_str = f' **({sub_s}分)**' if sub_s is not None else ''
                    st.markdown(f"{ic} **{si.get('name', si.get('requirement', ''))}**{score_str}: {si.get('detail', si.get('analysis', ''))}")
            if extra:
                st.caption(extra)

def score_bar(label: str, score: int, color: str=None, description: str=''):
    """评分进度条 — 极细"""
    if not color:
        if score >= 60:
            color = COLORS['primary']
        elif score >= 40:
            color = COLORS['accent']
        else:
            color = COLORS['danger']
    st.markdown(f"""\n    <div class="score-bar-wrap">\n        <div class="score-bar-label">\n            <span style="color:#0d1429;font-weight:500;">{label}</span>\n            <span style="font-weight:800;color:{color};">{score}</span>\n        </div>\n        <div class="score-bar-track">\n            <div class="score-bar-fill" style="width:{score}%;background:{color};"></div>\n        </div>\n        {(f'<div style="font-size:0.7rem;color:#999;margin-top:3px;">{description}</div>' if description else '')}\n    </div>\n    """, unsafe_allow_html=True)

def final_score_card(final_score, recommendation: str, reason: str, color: str=None):
    """综合评分卡。"""
    if final_score is None:
        display_score = '未生成'
        score_suffix = ''
        color = color or COLORS['warning']
    else:
        display_score = final_score
        score_suffix = '<span style="font-size:1.2rem;color:#999;font-weight:400;"> / 100</span>'
        if not color:
            if final_score >= 65:
                color = COLORS['primary']
            elif final_score >= 40:
                color = COLORS['accent']
            else:
                color = COLORS['danger']
    st.markdown(f'\n    <div class="final-score-card" style="border-color:{color};">\n        <div class="final-score-label">三维综合评分</div>\n        <div class="final-score-number" style="color:{color};">{display_score}{score_suffix}</div>\n        <div style="font-size:1.2rem;font-weight:800;color:{color};margin-top:16px;letter-spacing:-0.02em;">{recommendation}</div>\n        <div style="font-size:0.85rem;color:#666;margin-top:8px;">{reason}</div>\n    </div>\n    ', unsafe_allow_html=True)

def case_card(case_id, name, cause_type, goal_type, status, score=None, recommendation=None):
    """案件卡片"""
    status_map = {'draft': ('待评估', '#ffffff', '#0d1429'), 'pending': ('待评估', '#ffffff', '#0d1429'), 'evaluating': ('评估中', '#0d1429', '#ffffff'), 'completed': ('已完成', '#d65938', '#ffffff'), 'partial': ('部分完成', '#fff3cd', '#8a6d3b')}
    status_text, status_bg, status_color = status_map.get(status, ('未知', '#f5f5f5', '#666'))
    score_html = ''
    if score is not None:
        rec_color = COLORS['primary'] if score >= 65 else COLORS['accent'] if score >= 40 else COLORS['danger']
        rec_chip = '<span style="font-size:0.78rem;color:{rec_color};margin-left:8px;font-weight:600;">{recommendation}</span>'.format(rec_color=rec_color, recommendation=recommendation) if recommendation else ''
        score_html = '<div style="display:flex;align-items:baseline;gap:6px;margin-top:10px;"><span style="font-size:2rem;font-weight:800;color:{rec_color};letter-spacing:-0.04em;">{score}</span><span style="font-size:0.75rem;color:#999;">/ 100</span>{rec_chip}</div>'.format(rec_color=rec_color, score=score, rec_chip=rec_chip)
    st.html(f'\n    <div class="case-card">\n        <div class="case-card-title">{name}</div>\n        <div class="case-card-meta">\n            {cause_type} · {goal_type} · ID: {case_id}\n        </div>\n        <div style="margin-top:10px;display:flex;justify-content:space-between;align-items:flex-end;">\n            <span class="status-badge" style="background:{status_bg};color:{status_color};border-color:{status_color};">{status_text}</span>\n            {score_html}\n        </div>\n    </div>\n    ')

def chat_bubble(role_name: str, step_name: str, content: str, role_type: str='plaintiff', truncate: int=0):
    """模拟法庭聊天气泡 — 白底+左色条
    truncate: >0 时仅显示前 N 字，其余用 st.expander 折叠，无需 st.rerun()
    """
    rc = ROLE_COLORS.get(role_type, ROLE_COLORS['plaintiff'])
    color = rc['color']
    if role_type == 'defendant':
        margin = 'margin-left:15%;'
    elif role_type == 'judge':
        margin = 'margin:0 8%;'
    else:
        margin = 'margin-right:15%;'
    full_len = len(content)
    needs_expand = truncate and full_len > truncate
    content_display = content[:truncate] + '…' if needs_expand else content
    st.markdown(f'\n    <div class="chat-bubble" style="border-left-color:{color};{margin}">\n        <div class="chat-bubble-header">\n            <span style="color:{color};">{role_name}</span>\n            <span class="chat-role-tag" style="border-color:{color};color:{color};">{step_name}</span>\n        </div>\n        <div class="chat-bubble-content">{content_display}</div>\n    </div>\n    ', unsafe_allow_html=True)
    if needs_expand:
        with st.expander(f'展开全部（全文 {full_len} 字）'):
            st.markdown(content)

def metric_card(label: str, value: str, sub: str='', color: str=None):
    """指标卡 — 极简"""
    if not color:
        color = COLORS['primary']
    st.markdown(f"""\n    <div class="metric-card-wrap" style="border-color:{color};">\n        <div class="metric-card-label">{label}</div>\n        <div class="metric-card-value" style="color:{color};">{value}</div>\n        {(f'<div class="metric-card-sub">{sub}</div>' if sub else '')}\n    </div>\n    """, unsafe_allow_html=True)

def form_section_title(title: str):
    """表单分区标题"""
    st.markdown(f'<div class="form-section-title">{title}</div>', unsafe_allow_html=True)

def empty_state_notice(message: str):
    """统一空状态提示：橙色边框，黑色文字。"""
    st.markdown(f'<div class="empty-state-notice">{message}</div>', unsafe_allow_html=True)

def accent_notice(message: str):
    """统一浅橙提示块。"""
    st.markdown(f'<div class="accent-notice">{message}</div>', unsafe_allow_html=True)